document.documentElement.classList.add("js");
const toggle=document.querySelector("[data-menu-toggle]"),navigation=document.querySelector("[data-primary-navigation]");
if(toggle&&navigation)toggle.addEventListener("click",()=>{const open=toggle.getAttribute("aria-expanded")!=="true";toggle.setAttribute("aria-expanded",String(open));navigation.classList.toggle("is-open",open)});
const modal=document.querySelector("[data-reservation-modal]"),form=document.querySelector("[data-reservation-form]"),formWrap=document.querySelector("[data-reservation-form-wrap]"),success=document.querySelector("[data-reservation-success]"),errorBox=document.querySelector("[data-reservation-errors]");let trigger=null;
const focusable=()=>modal?Array.from(modal.querySelectorAll('a[href],button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')).filter(item=>!item.closest("[hidden]")):[];
const close=()=>{if(!modal)return;modal.hidden=true;document.body.classList.remove("reservation-open");if(trigger)trigger.focus()};
const open=button=>{if(!modal||!form)return;trigger=button;modal.hidden=false;document.body.classList.add("reservation-open");const data=button.dataset,vehicleId=form.querySelector("[data-reservation-vehicle-id]");if(vehicleId)vehicleId.value=data.vehicleId||"";const title=modal.querySelector("[data-reservation-title]");if(title)title.textContent=data.vehicleTitle||"";const specifications=modal.querySelector("[data-reservation-specifications]");if(specifications)specifications.textContent=data.vehicleSpecifications||"";const image=modal.querySelector("[data-reservation-image]");if(image){image.replaceChildren();if(data.vehicleImage){const vehicleImage=document.createElement("img");vehicleImage.src=data.vehicleImage;vehicleImage.alt="";image.append(vehicleImage)}}requestAnimationFrame(()=>{const focus=modal.querySelector("[data-reservation-close]")||form;focus.focus()})};
document.querySelectorAll("[data-reservation-trigger]").forEach(button=>button.addEventListener("click",()=>open(button)));modal&&modal.querySelectorAll("[data-reservation-close]").forEach(button=>button.addEventListener("click",close));document.addEventListener("keydown",event=>{if(event.key==="Escape"&&modal&&!modal.hidden)close();if(event.key==="Tab"&&modal&&!modal.hidden){const items=focusable();if(!items.length)return;const first=items[0],last=items[items.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}});
const displayErrors=errors=>{if(!form||!errorBox)return;const messages=Object.values(errors).flat();form.querySelectorAll('[aria-invalid="true"]').forEach(field=>field.removeAttribute("aria-invalid"));Object.keys(errors).forEach(name=>{const field=form.elements.namedItem(name);if(field)field.setAttribute("aria-invalid","true")});errorBox.textContent=messages.join(" ");errorBox.focus()};
if(form)form.addEventListener("submit",async event=>{if(!window.fetch)return;event.preventDefault();if(!form.reportValidity())return;const submit=form.querySelector('[type="submit"]');if(submit){submit.disabled=true;submit.textContent="Sending…"}const data=new FormData(form);data.set("rentacar_ajax","1");try{const response=await fetch((window.rentacarVenezia&&window.rentacarVenezia.reservationUrl)||form.action,{method:"POST",body:data,credentials:"same-origin"}),body=await response.json();if(!body.success){displayErrors(body.data.errors||{request:["Please review the form and try again."]});return}formWrap&&formWrap.setAttribute("hidden","");success&&success.removeAttribute("hidden");const reference=modal&&modal.querySelector("[data-reservation-reference]");if(reference&&body.data.reference)reference.textContent=`Reference: ${body.data.reference}`;const heading=modal&&modal.querySelector("[data-reservation-success] h2");heading&&heading.focus()}catch(error){displayErrors({request:["We could not send the request. Please try again."]})}finally{if(submit){submit.disabled=false;submit.textContent="Send reservation request"}}});
